algorithm BubbleSort
    dimension numbers[5] as integer;
    define i as integer;
    define j as integer;
    define auxiliary as integer;
    for i <- 0 to 4 step 1 do
        read numbers[i];
    endFor
    for i <- 0 to 3 step 1 do
        for j <- 0 to 3 - i step 1 do
            if numbers[j] > numbers[j + 1] then
                auxiliary <- numbers[j];
                numbers[j] <- numbers[j + 1];
                numbers[j + 1] <- auxiliary;
            endIf
        endFor
    endFor
    for i <- 0 to 4 step 1 do
        write numbers[i];
    endFor
endAlgorithm
